import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { env } from "../lib/env";
import * as schema from "./schema";

/**
 * Reuse a single pool across hot reloads in development. Next.js can evaluate
 * this module multiple times; without the global cache each reload leaks a pool.
 */
const globalForDb = globalThis as unknown as {
  __launchpadSql?: ReturnType<typeof postgres>;
};

const sql =
  globalForDb.__launchpadSql ??
  postgres(env.DATABASE_URL, {
    max: env.NODE_ENV === "production" ? 10 : 4,
    idle_timeout: 20,
    connect_timeout: 10,
  });

if (env.NODE_ENV !== "production") globalForDb.__launchpadSql = sql;

export const db = drizzle(sql, { schema });
export type Database = typeof db;
export { sql };

