import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { organization } from "better-auth/plugins";
import { nextCookies } from "better-auth/next-js";
import { db } from "../db";
import * as schema from "../db/schema";
import { env } from "./env";

export const auth = betterAuth({
  baseURL: env.BETTER_AUTH_URL,
  secret: env.BETTER_AUTH_SECRET,
  database: drizzleAdapter(db, {
    provider: "pg",
    schema,
    // Every auth lookup goes through the adapter; transactions keep
    // sign-up (user + account + session) atomic.
    transaction: true,
  }),
  emailAndPassword: {
    enabled: true,
    minPasswordLength: 10,
    // Dev-friendly: no mail provider is configured. Flip this on together
    // with `emailVerification.sendVerificationEmail` before going live.
    requireEmailVerification: false,
    autoSignIn: true,
  },
  session: {
    expiresIn: 60 * 60 * 24 * 30,
    updateAge: 60 * 60 * 24,
    cookieCache: { enabled: true, maxAge: 5 * 60 },
  },
  user: {
    deleteUser: { enabled: true },
  },
  trustedOrigins: [env.NEXT_PUBLIC_APP_URL],
  plugins: [
    organization({
      allowUserToCreateOrganization: true,
      organizationLimit: 5,
      creatorRole: "owner",
      invitationExpiresIn: 60 * 60 * 48,
      // No transactional email provider in this starter. Invitations are
      // persisted and surfaced in the UI with a copyable accept link.
      sendInvitationEmail: async ({ id, email, organization: org }) => {
        const link = `${env.NEXT_PUBLIC_APP_URL}/accept-invitation/${id}`;
        console.info(`[invite] ${email} -> ${org.name}: ${link}`);
      },
    }),
    // Must stay last so cookies set inside server actions are persisted.
    nextCookies(),
  ],
});

export type Session = typeof auth.$Infer.Session;

