import { betterAuth } from "better-auth";
import { organization } from "better-auth/plugins";

/**
 * Throwaway config used only by `pnpm auth:generate` (Better Auth CLI).
 * It mirrors the plugin/field surface of src/lib/auth.ts without opening a
 * database connection, which keeps schema generation deterministic.
 */
export const auth = betterAuth({
  secret: "schema-generation-only-placeholder-secret",
  database: { provider: "pg" } as never,
  emailAndPassword: { enabled: true },
  user: { deleteUser: { enabled: true } },
  plugins: [organization({})],
});

