import type { PlanId, SubscriptionStatus } from "@/db/schema/saas";

export type Feature = "analytics" | "custom_domain" | "sso" | "audit_log" | "priority_support";

export interface PlanLimits {
  seats: number;
  projects: number;
  apiRequestsPerMonth: number;
}

export interface Plan {
  id: PlanId;
  name: string;
  tagline: string;
  priceMonthlyUsd: number;
  features: Feature[];
  limits: PlanLimits;
  /** Env var holding the Stripe price id for this plan (null = not purchasable). */
  stripePriceEnv: "STRIPE_PRICE_PRO_MONTHLY" | "STRIPE_PRICE_SCALE_MONTHLY" | null;
  highlights: string[];
}

export const PLANS: Record<PlanId, Plan> = {
  free: {
    id: "free",
    name: "Free",
    tagline: "Kick the tires",
    priceMonthlyUsd: 0,
    features: [],
    limits: { seats: 2, projects: 1, apiRequestsPerMonth: 1_000 },
    stripePriceEnv: null,
    highlights: ["1 project", "2 seats", "1,000 API requests / month", "Community support"],
  },
  pro: {
    id: "pro",
    name: "Pro",
    tagline: "For growing teams",
    priceMonthlyUsd: 29,
    features: ["analytics", "custom_domain"],
    limits: { seats: 10, projects: 10, apiRequestsPerMonth: 50_000 },
    stripePriceEnv: "STRIPE_PRICE_PRO_MONTHLY",
    highlights: [
      "10 projects",
      "10 seats",
      "50,000 API requests / month",
      "Usage analytics + custom domain",
    ],
  },
  scale: {
    id: "scale",
    name: "Scale",
    tagline: "For serious volume",
    priceMonthlyUsd: 99,
    features: ["analytics", "custom_domain", "sso", "audit_log", "priority_support"],
    limits: { seats: 50, projects: 100, apiRequestsPerMonth: 500_000 },
    stripePriceEnv: "STRIPE_PRICE_SCALE_MONTHLY",
    highlights: [
      "100 projects",
      "50 seats",
      "500,000 API requests / month",
      "SSO, audit log, priority support",
    ],
  },
};

export const PAID_PLANS: Plan[] = [PLANS.pro, PLANS.scale];

/** Statuses that keep paid entitlements while the plan is being paid for. */
const ACCESS_STATUSES: ReadonlySet<SubscriptionStatus> = new Set([
  "active",
  "trialing",
  "past_due",
]);

const DELINQUENT_STATUSES: ReadonlySet<SubscriptionStatus> = new Set(["past_due", "unpaid"]);

export interface Entitlements {
  plan: PlanId;
  status: SubscriptionStatus;
  /** Whether paid features/limits apply right now. */
  hasAccess: boolean;
  /** Payment problem: show a banner, keep access during the grace window. */
  isDelinquent: boolean;
  limits: PlanLimits;
  features: Feature[];
}

/**
 * Single source of truth for what an org can do. Pure so it can be unit tested
 * and reused on the client without importing Stripe.
 */
export function entitlementsFor(plan: PlanId, status: SubscriptionStatus): Entitlements {
  const definition = PLANS[plan] ?? PLANS.free;
  const hasAccess = definition.id === "free" || ACCESS_STATUSES.has(status);

  if (!hasAccess) {
    return {
      plan: "free",
      status,
      hasAccess: false,
      isDelinquent: DELINQUENT_STATUSES.has(status),
      limits: PLANS.free.limits,
      features: PLANS.free.features,
    };
  }

  return {
    plan: definition.id,
    status,
    hasAccess: true,
    isDelinquent: DELINQUENT_STATUSES.has(status),
    limits: definition.limits,
    features: definition.features,
  };
}

export function can(entitlements: Entitlements, feature: Feature): boolean {
  return entitlements.features.includes(feature);
}

export function planFromPriceId(priceId: string | null | undefined): PlanId | null {
  if (!priceId) return null;
  for (const plan of PAID_PLANS) {
    if (plan.stripePriceEnv && process.env[plan.stripePriceEnv] === priceId) return plan.id;
  }
  return null;
}

export function isPlanId(value: string): value is PlanId {
  return value === "free" || value === "pro" || value === "scale";
}

