  });

  it.each(["canceled", "unpaid", "incomplete", "incomplete_expired", "paused"] as SubscriptionStatus[])(
    "falls back to free limits when status is %s",
    (status) => {
      const ent = entitlementsFor("pro", status);
      expect(ent.hasAccess).toBe(false);
      expect(ent.plan).toBe("free");
      expect(ent.limits).toEqual(PLANS.free.limits);
      expect(can(ent, "analytics")).toBe(false);
    },
  );

  it("marks unpaid as delinquent", () => {
    expect(entitlementsFor("pro", "unpaid").isDelinquent).toBe(true);
  });

  it("falls back to free for an unknown plan id", () => {
    // Simulates bad data coming back from the database.
    const ent = entitlementsFor("enterprise" as never, "active");
    expect(ent.plan).toBe("free");
    expect(ent.limits).toEqual(PLANS.free.limits);
  });
});

describe("can", () => {
  it("exposes scale-only features on scale", () => {
    const ent = entitlementsFor("scale", "active");
    expect(can(ent, "sso")).toBe(true);
    expect(can(ent, "audit_log")).toBe(true);
    expect(entitlementsFor("pro", "active").features).not.toContain("sso");
  });
});

describe("planFromPriceId", () => {
  it("maps configured price ids to plans", () => {
    process.env.STRIPE_PRICE_PRO_MONTHLY = "price_pro_test";
    process.env.STRIPE_PRICE_SCALE_MONTHLY = "price_scale_test";
    expect(planFromPriceId("price_pro_test")).toBe("pro");
    expect(planFromPriceId("price_scale_test")).toBe("scale");
  });

  it("returns null for unknown or missing prices", () => {
    expect(planFromPriceId("price_unknown")).toBeNull();
    expect(planFromPriceId(null)).toBeNull();
  });
});

describe("plan catalogue", () => {
  it("prices paid plans above free and keeps limits monotonic", () => {
    expect(PLANS.free.priceMonthlyUsd).toBe(0);
    expect(PLANS.pro.priceMonthlyUsd).toBeGreaterThan(0);
    expect(PLANS.scale.priceMonthlyUsd).toBeGreaterThan(PLANS.pro.priceMonthlyUsd);
    expect(PLANS.pro.limits.seats).toBeGreaterThan(PLANS.free.limits.seats);
    expect(PLANS.scale.limits.apiRequestsPerMonth).toBeGreaterThan(
      PLANS.pro.limits.apiRequestsPerMonth,
    );
  });
});
